INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('f38fc5a1-ce25-4203-9427-4b99f17127ae', 'd4eb2f04-7abb-485c-94ae-d6aa46e99935', 'RAID Builder', 'Create RAID0: mdadm --create /dev/md0 --level=0 --raid-devices=2 /tmp/disk1.img /tmp/disk2.img 2>/dev/null; Run: cat /proc/mdstat | grep md0 | awk "{print $4}". What is the status?', 100, '$2b$10$ZEe.dt0cfmqrMXNEXhygJ.lvvJ6IJo9d5rP19XiqOWmsEUdDnfqE2');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('e888ce7b-c4a1-43db-ab33-228e246dd28d', 'd4eb2f04-7abb-485c-94ae-d6aa46e99935', 'Swap Creator', 'Create 50MB swap: dd if=/dev/zero of=/tmp/swap.img bs=1M count=50 && mkswap /tmp/swap.img && swapon /tmp/swap.img. Run: swapon --show | wc -l. How many swap devices (minus header)?', 100, '$2b$10$ngmzW7JFTcopIFtkh97tbOOhVb/dfPbPqa7wZNMNnQcpArwhaQTUW');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('a7fc1c5a-9ae3-445f-9ed3-724b2bbf2f3a', 'd4eb2f04-7abb-485c-94ae-d6aa46e99935', 'DF Detective', 'Run: df -h --output=source,size,used,avail,target | grep tmp | head -1. What is the mount point?', 75, '$2b$10$4GKOA70DzO58OKBFzKs8pe2oa0i5txlDveMShlft2a.8wL1oT84s6');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('0f9f0e4f-6793-4612-9753-efa1bd6f41ab', 'd4eb2f04-7abb-485c-94ae-d6aa46e99935', 'Fstab Editor', 'Add to /etc/fstab: /tmp/disk.img /mnt/data ext4 loop 0 0. Run: grep "/mnt/data" /etc/fstab | awk "{print $3}". What filesystem type is listed?', 100, '$2b$10$InM7Aeha9IFnKhK4GyN7VeTRYSqkzNAgNuVV81bm3fWuJQ/DU/Hii');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('6f8366fa-42d8-4c52-b28e-976230874df1', 'd4eb2f04-7abb-485c-94ae-d6aa46e99935', 'Inode Counter', 'Run: df -i / | tail -1 | awk "{print $4}". How many free inodes?', 100, '$2b$10$7qI1hPvQsmwVosOb3whqs.loJ4DizeWWZQaEYoR0sQcLTfyk6jC7a');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('5dc679d7-3572-4cbe-aa24-9195fd873254', 'd4eb2f04-7abb-485c-94ae-d6aa46e99935', 'Du Analyzer', 'Create files in /mnt/data (dd if=/dev/zero of=/mnt/data/bigfile bs=1M count=10). Run: du -sh /mnt/data | awk "{print $1}". What is the size?', 100, '$2b$10$3LfzTkGp3IGN0R7UnW/Z3OVZL3cxyGQoN2c41NL0Fan4/7.QPXsWy');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('59c6e5ae-be31-44c2-8748-0e936f958cff', 'd4eb2f04-7abb-485c-94ae-d6aa46e99935', 'UUID Finder', 'Run: blkid /dev/loop0 2>/dev/null | grep -o "UUID=\"[^ ]*\"" | head -1. What is the UUID format? (just answer "uuid" if you can see it)', 75, '$2b$10$8ZAu.uB3/zijpO16rL29POc934TrgBD8PqDK6e2aUKle3vpwozXxe');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('086e4155-5774-4158-90a4-f01461cae1f2', 'd4eb2f04-7abb-485c-94ae-d6aa46e99935', 'Fdisk Explorer', 'Run: fdisk -l /tmp/disk.img 2>/dev/null | head -5. What disk identifier type is shown?', 100, '$2b$10$lw5kwRc8uj2nXZG5jdZb3.TeiJJQHKYT12OBaQ5s6vutvjiG9NDEe');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('c89b8053-e33e-4f22-81ef-42de9bfafecc', 'd4eb2f04-7abb-485c-94ae-d6aa46e99935', 'Cleanup Crew', 'Run: umount /mnt/data && losetup -D && vgremove -f myvg 2>/dev/null; echo "storage_done". What is the output?', 75, '$2b$10$KqPsKQUw06TjCuDhqLtRnehfBdSIQ.LQtEqKri8L2SWRB2QiDDSDK');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('09bc5670-04a5-4046-b42a-0ad9eec9dc12', 'eb5f9027-80b5-4611-a37d-b3223cf314d2', 'Tar Crafter', 'Create /home/student/backup_data/ with 3 files (a.txt, b.txt, c.txt). Pack: tar czf /tmp/backup.tar.gz -C /home/student backup_data. Run: tar tzf /tmp/backup.tar.gz | wc -l. How many entries?', 75, '$2b$10$smnkRRQ2owERe6Rf1stl1.85PIOAbRdqjr9fRrzA9u82OUzf0S2Da');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('e9328df1-d904-4552-b322-323a5b0eecf8', 'eb5f9027-80b5-4611-a37d-b3223cf314d2', 'Cron Scheduler', 'Add cron job: echo "0 * * * * echo backup_ok > /tmp/cron_proof" | crontab -. Run: crontab -l | wc -l. How many cron entries?', 75, '$2b$10$dflIOcdID2OyNjiTyjHuwuXKLhnhrUXfdsaXBe57zkwlOPby.o0qy');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('90c73b34-8707-4e2b-b4f2-68a89241dc13', 'eb5f9027-80b5-4611-a37d-b3223cf314d2', 'Restore Tester', 'Create /tmp/restore_dir/. Extract backup: tar xzf /tmp/backup.tar.gz -C /tmp/restore_dir. Run: ls /tmp/restore_dir/backup_data/ | wc -l. How many files restored?', 100, '$2b$10$7aLk4zHE2j8a/umrVPQrxuIE38qaT43ZR66i./XaB9Oo0GM2Wrs32');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('fea92d42-660a-4cce-9deb-f8447d6af468', 'eb5f9027-80b5-4611-a37d-b3223cf314d2', 'Incremental Creator', 'Create new file d.txt. Create incremental: tar czf /tmp/incr.tar.gz -C /home/student/backup_data --newer=a.txt . Run: tar tzf /tmp/incr.tar.gz. What file is listed?', 100, '$2b$10$uGKlNVBv3NbYf4u4S8F0HuaAoGupHjcxgAfvrK85fRf70C3QxLdie');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('def8db48-69b6-480c-abed-b9159bb5dfc7', 'eb5f9027-80b5-4611-a37d-b3223cf314d2', 'rsync Master', 'Create /tmp/src_dir/ and /tmp/dst_dir/. Create file in src. Run: rsync -av /tmp/src_dir/ /tmp/dst_dir/ && ls /tmp/dst_dir/. What file is synced?', 100, '$2b$10$XDs4OxMsWjc.R3j0ijNWuO7hnhxS5YNEqEOvAeuT0b/6aiDl2rQCu');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('ad537243-b699-4517-9b28-406dfa47c004', 'eb5f9027-80b5-4611-a37d-b3223cf314d2', 'Exclusion Expert', 'Create files: log.txt, data.csv, log2.txt. Run: tar czf /tmp/no_logs.tar.gz --exclude="log*" -C /home/student/backup_data . Run: tar tzf /tmp/no_logs.tar.gz | grep -c log. How many log files included?', 100, '$2b$10$lnv9SC8r1d3bG4E5e0tGl.X7I680tX3bDmbB0h895NRBztcCi4W52');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('b30ff732-1418-4c30-a5ee-fba0ded106e6', 'eb5f9027-80b5-4611-a37d-b3223cf314d2', 'Compression Pro', 'Compare: tar czf /tmp/gz.tar.gz -C /home/student/backup_data . vs tar cJf /tmp/xz.tar.xz -C /home/student/backup_data . Run: ls -la /tmp/gz.tar.gz /tmp/xz.tar.xz | awk "{print $5, $9}". Which is smaller?', 100, '$2b$10$ED7V46kfJovUdA.APyMA0.lUXNYX5ZCCXa5eGSNS6o3OVKeCHFiv2');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('9e60e8dd-96fc-421f-882e-f1376141dd9c', 'eb5f9027-80b5-4611-a37d-b3223cf314d2', 'Verify Expert', 'Run: tar tzf /tmp/backup.tar.gz > /tmp/list.txt && md5sum /tmp/list.txt. What is the first 8 chars of the hash?', 100, '$2b$10$Nm32FDHTYR2g4FTSt8zp6eCdGPOm.85J8PnsiQqJxzUE0vkfXjY5O');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('a58e6509-173a-48bd-9807-2d26bf50772d', 'eb5f9027-80b5-4611-a37d-b3223cf314d2', 'Docker Backup', 'Run: docker run -d --name db-backup alpine:3.18 sleep 300. Then: docker export db-backup > /tmp/container_backup.tar && wc -c /tmp/container_backup.tar. How many bytes (approximately)?', 100, '$2b$10$2dbsUuoJksxWFf9Mvtp0YuN96JNkWRm2ZyJ9si2GAaeOWbXDAdXku');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('c2dc691c-e5da-478c-81d3-54bcfb6de98e', 'eb5f9027-80b5-4611-a37d-b3223cf314d2', 'Cron Checker', 'Run: cat /var/spool/cron/crontabs/root 2>/dev/null | head -1. What is the cron schedule?', 75, '$2b$10$QJxrFXaufggak2PrPSBzr.lgG3TV16Gz3MHevje48a6tcN995fG/6');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('acfff6cc-e9a2-4cd3-aede-d9a3ac0b222e', 'eb5f9027-80b5-4611-a37d-b3223cf314d2', 'Diff Backup', 'Create /tmp/original/file.txt with "old". Copy to /tmp/backup_version/. Change original to "new". Run: diff /tmp/original/file.txt /tmp/backup_version/file.txt. What is shown?', 100, '$2b$10$AJHJy5TXaEL53Ta4D/.ApO74C9lSu.uzoSq3tQpLpEIA28vNd6tCS');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('4bafcee9-56c0-4131-9a0b-4aadf653ecf4', 'eb5f9027-80b5-4611-a37d-b3223cf314d2', 'Archive Inspector', 'Run: file /tmp/backup.tar.gz. What is the detected type?', 75, '$2b$10$3eEaInvdPSU26UonkOhsf.NdeDoABnLX3mjvZIbAwU0UvyJqZevgC');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('052d23c2-0b05-4aa4-823d-df2a95dedd6d', 'eb5f9027-80b5-4611-a37d-b3223cf314d2', 'Cleanup Script', 'Create /home/student/cleanup.sh that removes /tmp/restore_dir, /tmp/incr.tar.gz, /tmp/gz.tar.gz, /tmp/xz.tar.xz and echoes "cleaned". chmod +x and run. What is the output?', 100, '$2b$10$lCTbgyoHuk.I5KEXj6qMS.IiJmWIGgFMivAZhsWfd5cBbZJvauxnC');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('8366e7b9-ff0e-4ad0-984e-d5461f09825c', 'eb5f9027-80b5-4611-a37d-b3223cf314d2', 'Checksum Verifier', 'Run: sha256sum /tmp/backup.tar.gz | awk "{print $1}" | wc -c. How many characters is the SHA256 hash?', 75, '$2b$10$7p.VK8jBgV2lfHnwCrntSerj4rzL1ASPnCvu56WoSUDNf8V2vYp7q');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('afd98ba6-1daf-41a9-a0a2-4164bbff97fe', 'eb5f9027-80b5-4611-a37d-b3223cf314d2', 'Date Stamped Backup', 'Run: tar czf /tmp/backup_$(date +%Y%m%d).tar.gz -C /home/student/backup_data . && ls /tmp/backup_*.tar.gz | wc -l. How many date-stamped backups?', 100, '$2b$10$FH8.fbqDurPLvAftmNoXu.eD1UDl9W/MYRhQJnv.H9IIzr0XFrIJ2');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('8712bf32-2aa8-4b18-bea5-ec2809de6d47', '884ee166-21d8-4336-a519-6ccdf111068c', 'iptables List', 'Run: iptables -L -n | head -3. What is the first chain name shown?', 50, '$2b$10$yNmShayj2B9vOqIwTnfPqu9.gjhdsWJ7f0QOPabAK3Du0tWkiHpQK');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('0f9edc68-2eaa-41b1-b654-076b3b51930a', '884ee166-21d8-4336-a519-6ccdf111068c', 'Rule Creator', 'Run: iptables -A INPUT -p tcp --dport 8080 -j ACCEPT && iptables -L INPUT -n | grep 8080. What target is shown?', 75, '$2b$10$nWDDKjCTWQYp9xjgwfldb.86Gm2nm0ZptSbty9Wp/sIzD19ClulQ2');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('96028f03-188b-4662-b955-7e9c3a4cdb5f', '884ee166-21d8-4336-a519-6ccdf111068c', 'Port Blocker', 'Run: iptables -A INPUT -p tcp --dport 9999 -j DROP && iptables -L INPUT -n | grep 9999. What target?', 75, '$2b$10$dISVPiokzFRIaXU3ETVNm.0r5hzKyl7VYsUyW9LANUg8YIT78Z4.a');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('94c6945a-80db-4df7-99bb-6f8865f5a2fc', '884ee166-21d8-4336-a519-6ccdf111068c', 'Rule Deleter', 'Run: iptables -D INPUT -p tcp --dport 9999 -j DROP && iptables -L INPUT -n | grep -c 9999. How many rules for port 9999?', 100, '$2b$10$PEV52i2Ngm.k88GSnfnm4elAZjki6fizGHcLFLYDFv2Q9/vI6PW8a');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('3999817e-26ee-4366-afd4-6f7cc3f59266', '884ee166-21d8-4336-a519-6ccdf111068c', 'Chain Creator', 'Run: iptables -N MYCHAIN && iptables -L | grep MYCHAIN. What chain name appears?', 100, '$2b$10$d1DydmiEoGX1gSQu0b91lepWLb6707hwzAdk6.2B/9MiyCAmxHZAa');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('2c12240d-9b8e-4fd2-a1b1-04d9f626c4cb', '884ee166-21d8-4336-a519-6ccdf111068c', 'IP Blocker', 'Run: iptables -A INPUT -s 10.10.10.10 -j DROP && iptables -L INPUT -n | grep 10.10.10.10. What target?', 100, '$2b$10$1mUC.5ZC21H24L4DdAhjRO.FLR8lrUu6rmHIBH2o6OcEbX8cWzWKC');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('38299ea7-0f42-4747-a416-cb666243e818', '884ee166-21d8-4336-a519-6ccdf111068c', 'Rate Limiter', 'Run: iptables -A INPUT -p tcp --dport 80 -m limit --limit 10/min --limit-burst 20 -j ACCEPT && iptables -L INPUT -n | grep "limit:10/min". Is limit shown? (yes/no)', 100, '$2b$10$Vg0wdsihN8fgg71fcF4wN.YyU8icyRC5RKQmwt4PbkCmTk3rZFVPu');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('c20fccb3-f6d4-418d-8469-fa604cc44345', '884ee166-21d8-4336-a519-6ccdf111068c', 'State Inspector', 'Run: iptables -A INPUT -m state --state ESTABLISHED,RELATED -j ACCEPT && iptables -L INPUT -n | grep ESTABLISHED. What states are listed?', 100, '$2b$10$u9RIlPd413Wl7Ab5PCmciu8DC3nsuMaUYrr.9Am8vfdGEiABAj9v6');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('da572fae-f4c2-459e-9e85-547e9033c494', '884ee166-21d8-4336-a519-6ccdf111068c', 'NAT Creator', 'Run: iptables -t nat -A PREROUTING -p tcp --dport 8080 -j REDIRECT --to-port 80 && iptables -t nat -L PREROUTING -n | grep 8080. What target?', 100, '$2b$10$3WIs186SYvHRG4TP9Mrn7.pzWIREW6g04arzhWTw2K/w3lExRWQNG');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('eaf3ac4d-ab25-40c8-a5ad-e1ec7b49cb62', '884ee166-21d8-4336-a519-6ccdf111068c', 'Rule Saver', 'Run: iptables-save > /tmp/iptables_rules.txt && wc -l /tmp/iptables_rules.txt. How many lines of rules?', 100, '$2b$10$iArDu7M9xnocm4Hu3n1ejexScs5/AsRtXRGdT1xfDjlELuN8ovvRq');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('a417f064-897d-4d8c-a158-2e14fb110839', '884ee166-21d8-4336-a519-6ccdf111068c', 'Log Logger', 'Run: iptables -A INPUT -p tcp --dport 8080 -j LOG --log-prefix "FIREWALL: " && iptables -L INPUT -n | grep LOG. What log prefix is shown?', 100, '$2b$10$9vX6f6hrEj2G.Bt4ij/Ucu1vZgHgA2T5cBpc2zC999lAiElxTevWy');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('c507f497-bda2-41c5-a893-3347514e1c5b', '884ee166-21d8-4336-a519-6ccdf111068c', 'Interface Binder', 'Run: iptables -A INPUT -i eth0 -j ACCEPT && iptables -L INPUT -n | grep eth0. What interface is shown?', 100, '$2b$10$c4P3ZXBAoRXn61Htq4oKEeqXYWVneMpS5Yo5DVZr.oUidvLK.Plyq');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('8d49a479-0d38-43b4-aeaf-b2304ee5de64', '884ee166-21d8-4336-a519-6ccdf111068c', 'Packet Counter', 'Run: iptables -Z INPUT && iptables -L INPUT -v -n | head -3. What is the pkts count for INPUT chain?', 100, '$2b$10$7YhlpzWuSruNIcjGvwQ2veq8XQ86vgbx93XpEln3Jh8xnZjZKP2C.');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('eaf453b1-0342-4b2d-8eb9-b0fa2b223d28', '884ee166-21d8-4336-a519-6ccdf111068c', 'Flush Master', 'Run: iptables -F MYCHAIN && iptables -L MYCHAIN -n | wc -l. How many rules in MYCHAIN after flush?', 75, '$2b$10$7v4W7DyYM.Rep.WFkxUWxOnBjZashRaDc8P9DL0i3W9ucQxadam3.');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('417bd77e-8888-4055-b610-02592f61658e', '884ee166-21d8-4336-a519-6ccdf111068c', 'Cleanup', 'Run: iptables -F && iptables -X MYCHAIN 2>/dev/null; iptables -t nat -F PREROUTING 2>/dev/null; echo "firewall_done". What is the output?', 75, '$2b$10$DL6d6iQsx3oO3mwfvOyzn.jP9JWWk7p89SIYwMrNRK6k3Vu8cnBXu');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('b29b4355-55ce-4561-83a5-245f56ab0e7d', 'e0decd06-4a2e-4f94-965a-79854928514d', 'Zone Creator', 'Create zone file: /etc/bind/zones/aeroacademy.local. Add SOA record for aeroacademy.local. Run: named-checkzone aeroacademy.local /etc/bind/zones/aeroacademy.local 2>&1 | tail -1. What is the status?', 75, '$2b$10$AIzvv0zFKBHtmg9zdW.stuyi6olwe0QIs.0gG9AFWTWP0J7qLzedS');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('d000c692-e961-4cd4-a610-c2e50c1eb17f', 'e0decd06-4a2e-4f94-965a-79854928514d', 'A Record', 'Add A record: aeroacademy.local IN A 192.168.1.100. Run: grep "IN A" /etc/bind/zones/aeroacademy.local. What IP is shown?', 75, '$2b$10$c1CNWNoz/eFFdRaFyh4axOFqeDQztomvA62FEt5ehFq0cDMhPQPOe');
