INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('7bcfd5bf-b4c2-455b-8b47-56e0aeaaa9e0', '50d6a493-7898-473d-8287-137229593da9', 'Reverse Proxy', 'Start a python http server on port 8888: python3 -m http.server 8888 &. Create nginx reverse proxy config on port 9091 proxying to localhost:8888. Reload nginx. Run: curl -s localhost:9091. What HTML title is shown?', 100, '$2b$10$2nZAqrWORdawZbneF/J1zepDu34tW9Hw/Wcb.74CFnmhRCVWZSX3a');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('6f65c99d-f40e-4f42-8abb-a554d1198210', '50d6a493-7898-473d-8287-137229593da9', 'SSL Generator', 'Create /etc/nginx/ssl/ directory. Generate self-signed cert: openssl req -x509 -nodes -days 365 -newkey rsa:2048 -keyout /etc/nginx/ssl/key.pem -out /etc/nginx/ssl/cert.pem -subj "/CN=localhost". Run: openssl x509 -in /etc/nginx/ssl/cert.pem -noout -subject. What is the CN value?', 100, '$2b$10$/FTxP1TxTTZJrVPrP8tke.8CU49H4mzzfRt.r4at/FuxQ0cym9XyG');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('a26f479d-e945-4dcd-9b14-67bdb1d8235c', '50d6a493-7898-473d-8287-137229593da9', 'Rate Limiter', 'Add to your nginx server config: limit_req_zone $binary_remote_addr zone=one:10m rate=1r/s;. Then add limit_req zone=one burst=5 nodelay to a location block. Reload. Run: for i in 1 2 3 4 5 6; do curl -s -o /dev/null -w "%{http_code} " localhost:9090; done. What HTTP codes appear (space-separated)?', 100, '$2b$10$7DLHa074eJ4JNH25CwZBO.tAxPOTJMwBSXWIWQ8MHQYV0DPecfh1W');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('c69b9ac4-8475-45d6-9dbc-8d6c47abe021', '50d6a493-7898-473d-8287-137229593da9', 'Gzip Optimizer', 'Add gzip on; gzip_types text/plain; to the http block in /etc/nginx/nginx.conf. Reload nginx. Run: curl -s -H "Accept-Encoding: gzip" -D - localhost 2>&1 | grep -i content-encoding. What encoding is shown?', 100, '$2b$10$d9Wkv8NKrXkq2pXkNhtfJO16.Bdwh4iud2NKjPvZsQ5OLUFiNutSy');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('22d9787c-8a60-45ba-adc1-d8a7f283814c', '50d6a493-7898-473d-8287-137229593da9', 'Load Balancer', 'Start 2 python servers on ports 8889 and 8890 (python3 -m http.server 8889 & and python3 -m http.server 8890 &). Create nginx upstream config on port 9092 load balancing between them. Reload and curl localhost:9092. What is the upstream block name you used?', 100, '$2b$10$OE/IB6N6ZhcAS3rF08rjUeNUPXl29DhXCjp5xq7kFvx2Ya8lkxvPW');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('f74a5f88-ad1f-45f2-9f7e-cd07e0f2f09e', '50d6a493-7898-473d-8287-137229593da9', 'Access Control', 'Create a location block for /private with "allow 127.0.0.1; deny all;". Reload nginx. Run: curl -s -o /dev/null -w "%{http_code}" localhost:9090/private. What status code?', 100, '$2b$10$.BmIvbKm3hLnq36ULqyghOcPhsAs04OR.lIYmqRPP3jTbgMCkGPkO');
INSERT INTO "LabFlag" (id, "labId", title, description, points, "correctAnswer") VALUES ('d70da634-59fa-4e01-99b7-32a7bcb709d7', '50d6a493-7898-473d-8287-137229593da9', 'Error Page Customizer', 'Create /var/www/mysite/404.html with "Page Not Found". Add error_page 404 /404.html to your server block. Reload. Run: curl -s localhost:9090/nonexistent. What is the content?', 100, '$2b$10$g0RIVA25K6NoqC6dW6aQSe1O/Xw0JTxyF6BYawT/L752YX.lBfUsu');
